export const videoBrandingCss=`.vb-stage{position:relative;flex-shrink:0;margin:0 auto;background:#02070c;max-width:100%}.vb-stage .vw-player{width:100%;height:100%;max-height:none;min-height:0;display:block;object-fit:contain}.vb-overlay{position:absolute;inset:0;width:100%;height:100%;touch-action:none;pointer-events:none}.vb-overlay.vb-edit{pointer-events:auto;cursor:move}.vb-panel{margin:10px 0;border:1px solid var(--line);border-radius:10px;padding:12px}.vb-panel textarea{width:100%;min-height:100px;font:inherit;color:inherit;background:#101e29;border:1px solid var(--line);border-radius:8px;padding:10px}.vb-panel input:not([type=checkbox]){width:100%}.vb-layers{display:grid;gap:7px;margin:12px 0}.vb-layers button{text-align:left;overflow-wrap:anywhere}.vb-help{line-height:1.6;font-size:15px;color:#bfced6}.vb-time{width:100%}.vw-grid{min-height:0;grid-template-rows:minmax(0,1fr)}.vw-side{min-height:0}.vb-panel summary{font-weight:700}@media(min-width:1101px){.vw-grid{grid-template-columns:250px minmax(0,1fr) 360px}}`;

// Local canvas and shared image branding renderer keep preview and encoded placement proportional.
export function videoBrandingPanel({host,stage,player,language,imageFactory,rendererFactory,brandFactory,labels,getProject,commit,isBusy,isResult,getTime,seek,onError}){
 const I=imageFactory(),B=brandFactory(),t=labels(language),D=document,el=(tag,text='',cls='')=>{const x=D.createElement(tag);x.textContent=text;x.className=cls;return x;},canvas=el('canvas','','vb-overlay'),panel=el('details','','vb-panel'),body=el('div'),summary=el('summary',t.title),time=el('input','','vb-time'),hint=el('p',t.position,'vb-help');panel.open=true;panel.append(summary,body);host.append(panel);stage.append(canvas);stage.after(hint,time);canvas.tabIndex=0;canvas.setAttribute('aria-label',t.position);time.type='range';time.min='0';time.step='.01';time.setAttribute('aria-label',t.time);
 const renderer=rendererFactory(()=>D.createElement('canvas'),I),logos=new Map();let selected='',shelf={brands:[]},replace=true,drawing=0,drag=null,temporary=null;
 function fail(){onError(Error(t.error));}
 function readProfiles(){try{shelf=I.readBrandShelf(localStorage).value;}catch{fail();shelf={brands:[]};}}
 const btn=(parent,key,fn)=>{const b=el('button',t[key]);b.type='button';b.dataset.vbAction=key;b.disabled=isBusy();b.addEventListener('click',fn);parent.append(b);return b;};
 const project=()=>temporary||getProject(),picked=()=>project().branding?.find(b=>b.id===selected);
 function update(fn){if(isBusy())return;try{const p=getProject();fn(p);p.branding=B.normalize(p.branding);commit(p);}catch{fail();}}
 function set(key,value,layer=false){update(p=>{const b=p.branding.find(b=>b.id===selected);if(b)(layer?b.layer:b)[key]=value;});if(['start','end','fadeIn','fadeOut'].includes(key))reveal();}
 function field(parent,key,value,{type='number',min=0,max=1800,step=.1,change}={}){const l=el('label',t[key]),x=el(type==='textarea'?'textarea':'input');if(type!=='textarea')x.type=type;x.value=String(value);x.min=min;x.max=max;x.step=step;x.disabled=isBusy();x.dataset.vbField=key;if(type==='textarea')x.maxLength=600;x.addEventListener('change',()=>change(type==='number'?Number(x.value):x.value));l.append(x);parent.append(l);return x;}
 function check(parent,key,value,change){const l=el('label'),x=el('input');x.type='checkbox';x.checked=value;x.disabled=isBusy();x.dataset.vbField=key;x.addEventListener('change',()=>change(x.checked));l.append(x,D.createTextNode(t[key]));parent.append(l);}
 function select(parent,key,value,choices,change){const l=el('label',t[key]),s=el('select');s.dataset.vbField=key;s.disabled=isBusy();for(const [v,label]of choices){const o=el('option',label);o.value=v;s.append(o);}s.value=value;s.addEventListener('change',()=>change(s.value));l.append(s);parent.append(l);return s;}
 async function logoImage(data){if(!logos.has(data)){const promise=new Promise((ok,no)=>{const img=new Image();img.onload=()=>img.width>0&&img.height>0&&img.width*img.height<=4194304?ok(img):no(Error('Logo size'));img.onerror=no;img.src=data;});logos.set(data,promise);if(logos.size>20)logos.delete(logos.keys().next().value);}return logos.get(data);}
 async function paintLayer(target,b){const x=target.getContext('2d');x.clearRect(0,0,target.width,target.height);x.globalAlpha=b.layer.opacity/100;renderer.drawBrand(x,b.layer,target.width,target.height,b.logo?await logoImage(b.logo):null);x.globalAlpha=1;}
 async function draw(){const stamp=++drawing;try{const p=project(),a=p.assets.find(a=>a.id===p.clips[0]?.asset);if(!a||isResult()){canvas.hidden=true;return;}canvas.hidden=false;const ratio=a.width/a.height;stage.style.aspectRatio=String(ratio);stage.style.width=`min(100%, calc(48dvh * ${ratio}))`;const scale=Math.min(1,1280/a.width),w=Math.round(a.width*scale),h=Math.round(a.height*scale);canvas.width=w;canvas.height=h;const x=canvas.getContext('2d'),total=p.clips.reduce((n,c)=>n+(c.out-c.in)/c.speed,0),now=getTime();for(const b of p.branding||[]){const alpha=B.alpha(b,now,total);if(!alpha)continue;const img=b.logo?await logoImage(b.logo):null;if(stamp!==drawing)return;x.globalAlpha=alpha*b.layer.opacity/100;renderer.drawBrand(x,b.layer,w,h,img);}x.globalAlpha=1;}catch{if(stamp===drawing)fail();}}
 function reveal(){const b=picked(),p=getProject(),total=p.clips.reduce((n,c)=>n+(c.out-c.in)/c.speed,0);if(!b||!total)return;const t=B.timing(b,total);if(t.end>t.start&&B.alpha(b,getTime(),total)<.5){seek(Math.min(t.end-.01,t.start+Math.max(.04,t.fadeIn)));void draw();}}
 function addText(){update(p=>{const b=B.text(t.words);selected=b.id;p.branding.push(b);});reveal();}
 async function importLogo(file){if(!file||isBusy())return;try{if(file.size>8000000||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error();const image=await createImageBitmap(file);try{if(image.width*image.height>24000000)throw Error();const c=D.createElement('canvas'),s=Math.min(1,2048/Math.max(image.width,image.height));c.width=Math.round(image.width*s);c.height=Math.round(image.height*s);c.getContext('2d').drawImage(image,0,0,c.width,c.height);const logo=c.toDataURL('image/png');update(p=>{const b=B.text(file.name);b.layer.kind='image';b.layer.name=file.name;b.layer.brandSize=.18;b.logo=logo;selected=b.id;p.branding.push(b);});reveal();}finally{image.close?.();}}catch{fail();}}
 const logoInput=el('input');logoInput.type='file';logoInput.accept='image/png,image/jpeg,image/webp';logoInput.hidden=true;host.append(logoInput);logoInput.addEventListener('change',()=>{void importLogo(logoInput.files?.[0]);logoInput.value='';});
 function applyProfile(id){if(isBusy())return;try{const profile=shelf.brands.find(b=>b.id===id);if(!profile)throw Error();const incoming=B.fromProfile(profile);update(p=>{p.branding=replace?incoming:[...p.branding,...incoming];selected=incoming[0]?.id||'';});reveal();}catch{fail();}}
 function refresh(){const p=getProject(),total=p.clips.reduce((n,c)=>n+(c.out-c.in)/c.speed,0);if(selected&&!p.branding.some(b=>b.id===selected))selected='';body.replaceChildren();const actions=el('div','','vw-row');body.append(actions);btn(actions,'add',addText);btn(actions,'logo',()=>logoInput.click());const picker=select(body,'profile','',[['',t.choose],...shelf.brands.map(b=>[b.id,b.name])],()=>{});const profileActions=el('div','','vw-row');body.append(profileActions);btn(profileActions,'apply',()=>applyProfile(picker.value));btn(profileActions,'reload',()=>{readProfiles();refresh();});check(body,'replace',replace,v=>{replace=v;});const list=el('div','','vb-layers');body.append(list);for(const b of p.branding){const item=el('button',(b.enabled?'● ':'○ ')+(b.layer.kind==='text'?b.layer.words:b.layer.name).slice(0,70));item.type='button';item.dataset.vbLayer=b.id;item.disabled=isBusy();item.setAttribute('aria-pressed',String(selected===b.id));item.addEventListener('click',()=>{selected=b.id;refresh();reveal();});list.append(item);}const b=p.branding.find(b=>b.id===selected);if(b){check(body,'enabled',b.enabled,v=>set('enabled',v));if(b.layer.kind==='text'){field(body,'words',b.layer.words,{type:'textarea',change:v=>set('words',v,true)});select(body,'font',b.layer.font,['sans','serif','mono'].map(k=>[k,t[k]]),v=>set('font',v,true));field(body,'ink',b.layer.ink,{type:'color',change:v=>set('ink',v,true)});check(body,'bold',b.layer.bold,v=>set('bold',v,true));check(body,'plate',b.layer.plate,v=>set('plate',v,true));}field(body,'size',100*(b.layer.kind==='text'?b.layer.fontSize:b.layer.brandSize),{min:b.layer.kind==='text'?1:3,max:b.layer.kind==='text'?25:80,step:.5,change:v=>set(b.layer.kind==='text'?'fontSize':'brandSize',v/100,true)});field(body,'opacity',b.layer.opacity,{max:100,step:1,change:v=>set('opacity',v,true)});select(body,'anchor',b.layer.anchor,I.brandAnchors.map((k,i)=>[k,t.anchors.split(',')[i]]),v=>update(p=>I.snapBrand(p.branding.find(x=>x.id===selected).layer,v)));for(const key of ['x','y'])field(body,key,b.layer[key]*100,{min:-200,max:300,step:1,change:v=>set(key,v/100,true)});check(body,'repeat',b.layer.repeat,v=>set('repeat',v,true));for(const key of ['start','end','fadeIn','fadeOut'])field(body,key,b[key],{max:key.startsWith('fade')?5:1800,step:.05,change:v=>set(key,v)});const order=el('div','','vw-row');body.append(order);for(const [key,delta]of [['earlier',-1],['later',1]])btn(order,key,()=>update(p=>{const i=p.branding.findIndex(b=>b.id===selected),j=i+delta;if(j>=0&&j<p.branding.length)[p.branding[i],p.branding[j]]=[p.branding[j],p.branding[i]];}));btn(order,'remove',()=>update(p=>{p.branding=p.branding.filter(b=>b.id!==selected);selected='';}));}const help=el('details');help.append(el('summary',t.title+' · ?'),el('p',t.help,'vb-help'));body.append(help);time.max=String(total);time.value=String(Math.min(total,getTime()));time.disabled=isBusy()||!total||isResult();canvas.className='vb-overlay'+(selected&&!isResult()&&!isBusy()?' vb-edit':'');void draw();}
 async function frames(dimensions,signal){const check=()=>{if(signal?.aborted)throw new DOMException('Cancelled','AbortError');};check();await D.fonts?.ready;check();const p=getProject(),total=p.clips.reduce((n,c)=>n+(c.out-c.in)/c.speed,0),out=[];for(const b of B.active(p.branding,total)){check();const c=D.createElement('canvas');c.width=dimensions.width;c.height=dimensions.height;await paintLayer(c,b);check();out.push({id:b.id,width:c.width,height:c.height,data:c.toDataURL('image/png')});c.width=c.height=1;}return out;}
 time.addEventListener('input',()=>{seek(Number(time.value));void draw();});for(const event of ['loadedmetadata','timeupdate','seeked','pause'])player.addEventListener(event,()=>{time.value=String(getTime());void draw();});
 canvas.addEventListener('pointerdown',e=>{if(isBusy()||isResult()||!picked())return;e.preventDefault();drag={x:e.clientX,y:e.clientY,before:getProject()};canvas.setPointerCapture?.(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!drag)return;const r=canvas.getBoundingClientRect();temporary=B.clone(drag.before);const l=temporary.branding.find(b=>b.id===selected)?.layer;if(l){l.x=I.bounded(l.x+(e.clientX-drag.x)/r.width,-2,3,.5);l.y=I.bounded(l.y+(e.clientY-drag.y)/r.height,-2,3,.5);void draw();}});canvas.addEventListener('pointerup',()=>{if(!drag)return;const next=temporary;temporary=null;drag=null;if(next)commit(next);});canvas.addEventListener('pointercancel',()=>{drag=null;temporary=null;void draw();});canvas.addEventListener('keydown',e=>{if(isBusy()||!picked()||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const axis=['ArrowLeft','ArrowRight'].includes(e.key)?'x':'y',delta=(['ArrowLeft','ArrowUp'].includes(e.key)?-1:1)*(e.shiftKey ? .05 : .01);set(axis,picked().layer[axis]+delta,true);});
 window.addEventListener('storage',e=>{if(e.key===I.brandShelfKey){readProfiles();refresh();}});readProfiles();
 return {panel,refresh,frames,draw,addText,applyProfile,importLogo};
}
